CREATE POLICY "Owners upload profile photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'profile-photos' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY "Owners read profile photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'profile-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owners remove profile photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'profile-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE OR REPLACE FUNCTION public.update_profile_photo(_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF; IF _path !~ ('^' || auth.uid()::text || '/[a-zA-Z0-9-]+\.(jpg|jpeg|png|webp)$') THEN RAISE EXCEPTION 'Invalid photo path'; END IF; IF NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id='profile-photos' AND name=_path) THEN RAISE EXCEPTION 'Photo not found'; END IF; UPDATE public.profiles SET avatar_url = 'perk-photo:' || _path WHERE id = auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Profile not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.update_profile_photo(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_profile_photo(text) TO authenticated;